def get_lang(request) -> str:
    v = request.cookies.get(COOKIE, DEFAULT_LANG)
    return v if v in SUPPORTED else DEFAULT_LANG


def t(lang: str, key: str, **kwargs) -> str:
    lang = lang if lang in SUPPORTED else DEFAULT_LANG
    s = STRINGS.get(lang, {}).get(key)
    if s is None:
        s = STRINGS['en'].get(key, key)
    return s.format(**kwargs) if kwargs else s


JS_KEYS = [k for k in STRINGS['en'] if k.startswith('js.')]


def js_dict(lang: str) -> dict:
    return {k: t(lang, k) for k in JS_KEYS}


def vl(lang: str, value):
    """Translate a finite DB-driven value (status/type/role/etc.) for display."""
    if not value:
        return value
    return VALUE_LABELS.get(lang, {}).get(value, value)
